import{_ as t,o as e,c as o,a5 as r}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"随机数生成","description":"Generate Random Fractions with JavaScript 计算机的行为只有两种：确定性和随机性。当你一步步地闯关来到这里就是确定行为，当你随意点了个链接就来到这里就是随机行为。 而随机数最适合用来创建这种随机行为。 Math.random() 用来生成一。","frontmatter":{"title":"随机数生成","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","面试与手写"],"description":"Generate Random Fractions with JavaScript 计算机的行为只有两种：确定性和随机性。当你一步步地闯关来到这里就是确定行为，当你随意点了个链接就来到这里就是随机行为。 而随机数最适合用来创建这种随机行为。 Math.random() 用来生成一。","sidebarWeight":37,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/面试题/随机数生成.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/09-面试与手写/随机数生成.md","filePath":"posts/JavaScript系统教程/09-面试与手写/随机数生成.md"}'),n={name:"posts/JavaScript系统教程/09-面试与手写/随机数生成.md"};function i(s,a,d,m,c,l){return e(),o("div",null,[...a[0]||(a[0]=[r('<div><h1 id="随机数生成" tabindex="-1">随机数生成 <a class="header-anchor" href="#随机数生成" aria-label="Permalink to &quot;随机数生成&quot;">​</a></h1><blockquote><p>本节目标：理解“随机数生成”的核心思路，并能把它用于实际开发或面试表达。 ==Generate Random Fractions with JavaScript== 计算机的行为只有两种：确定性和随机性。当你一步步地闯关来到这里就是确定行为，当你随意点了个链接就来到这里就是随机行为。 而随机数最适合用来创建这种随机行为。 ==Math.random()==用来生成一个在0(包括0)到1(不包括1)之间的随机小数，因此==Math.random()==可能返回0但绝不会返回1。 <strong>提示</strong> 随后的函数都会在==return==执行前调用，所以我们可以直接返回==Math.random()==的值。 任务 更改==myFunction== 来生成一个随机数取代 ==0==。</p></blockquote><p>==Generate Random Whole Numbers with JavaScript== 生成随机小数很棒，但随机数更有用的地方在于生成随机整数。</p><ol><li>用 ==Math.random()== 生成一个随机小数。</li><li>把这个随机小数乘以 ==20==。</li><li>用 ==Math.floor()== 向下取整 获得它最近的整数。</li></ol><p>记住 ==Math.random()== 永远不会返回 ==1==。同时因为我们是在用 ==Math.floor()== 向下取整，所以最终我们获得的结果不可能有 ==20==。这确保了我们获得了一个在0到19之间的整数。 把操作连缀起来，代码类似于下面： ==Math.floor(Math.random() * 20);== 我们先调用 ==Math.random()==，把它的结果乘以20，然后把上一步的结果传给 ==Math.floor()==，最终通过向下取整获得最近的整数。 任务 生成一个 ==0== 到 ==9==之间的随机整数。</p><p>==Generate Random Whole Numbers within a Range== 我们之前生成的随机数是在0到某个数之间，现在我们要生成的随机数是在两个指定的数之间。 我们需要定义一个最小值和一个最大值。 下面是我们将要使用的方法，仔细看看并尝试理解这行代码到底在干嘛： ==Math.floor(Math.random() * (max - min + 1)) + min== 任务 创建一个叫==randomRange==的函数，参数为myMin和myMax，返回一个在==myMin==(包括myMin)和==myMax==(包括myMax)之间的随机数。</p></div>',1)])])}const _=t(n,[["render",i]]);export{h as __pageData,_ as default};
